-- Сид разработки backend-pos (контракт M2 §3): меню бара тестового клуба и начальные остатки.
-- Только разработка (decisions №21): в проде меню пустое, клуб заводит его сам или импортом CSV.
-- Повторный запуск ничего не дублирует и не меняет то, что уже изменено вручную.
--
-- Фиксированные UUID: категории ca…0N, товары cb…NN, группы модификаторов cc…0N,
-- модификаторы cd…NN, приходы склада ce…NN. Цены — копейки. Пиво — is_alcohol: в QR-меню
-- его нет, пока платформа не включила qr_alcohol_allowed (decisions №76); ресепшн продаёт.

-- Настройки кассы клуба: лимит скидки ресепшена 10 %, стоп-лист при нулевом остатке,
-- почта для чека ЮKassa при СБП на кассе без телефона покупателя (синтетическая).
update bl.clubs
   set settings = jsonb_build_object('pos_discount_limit_percent', 10, 'pos_stop_at_zero', true,
                                     'pos_receipt_email', 'kassa@billiardum.test') || settings
 where id = 'c1000000-0000-4000-8000-000000000001'
   and not (settings ? 'pos_discount_limit_percent');

on conflict (id) do nothing;

on conflict (id) do nothing;

-- Объём: 0,3 л (по умолчанию) и 0,4 л (+40 ₽, списывает 1,3 порции); сахар — выбор обязателен.
on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (product_id, group_id) do nothing;

-- Начальные остатки — приходы с себестоимостью (синтетика), от имени владельца тестового клуба.
on conflict (id) do nothing;
